exercise.referenceSolution:
struct Filter { virtual bool accept(int x) const = 0; virtual ~Filter() = default; };
struct NonNegative : Filter { bool accept(int x) const override { return x>=0; } };
int sum_selected(int a,int b,const Filter& f) { int total=0; if(f.accept(a)) total+=a; if(f.accept(b)) total+=b; return total; }
int solve(int a,int b) { NonNegative f; return sum_selected(a,b,f); }
